class Solution:
    def getSum(self, a: int, b: int) -> int:
        # This deliberately avoids + and - in the repeated adjustment.
        while b > 0:
            a = a.__add__(1)
            b = b.__sub__(1)
        while b < 0:
            a = a.__sub__(1)
            b = b.__add__(1)
        return a

